using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;

public class RebuildIdle6Frames
{
    [MenuItem("Flynn/Rebuild Idle Clips (6 frames)")]
    public static void Rebuild()
    {
        // Load the Idle spritesheet
        var idleAsset = AssetDatabase.LoadAssetAtPath<Texture2D>(
            "Assets/Flynn/Sprites/character_animations/FINAL_ANIMATIONS/IDLE/Idle.png");
        if (idleAsset == null) { Debug.LogError("Idle.png not found"); return; }

        string idlePath = AssetDatabase.GetAssetPath(idleAsset);
        var idleGUID = AssetDatabase.AssetPathToGUID(idlePath);

        // Load all sprites from the sheet
        var allSprites = AssetDatabase.LoadAllAssetsAtPath(idlePath);
        System.Collections.Generic.Dictionary<string, Sprite> spriteMap = new System.Collections.Generic.Dictionary<string, Sprite>();
        foreach (var obj in allSprites)
        {
            var sp = obj as Sprite;
            if (sp != null) spriteMap[sp.name] = sp;
        }

        // Frame indices to keep (0-5, drop 6 and 7) per direction
        int[][] frameSets = new int[][]
        {
            new int[] { 0, 1, 2, 3, 4, 5 },   // Down: Idle_0..Idle_5
            new int[] { 8, 9, 10, 11, 12, 13 }, // Up: Idle_8..Idle_13
            new int[] { 16, 17, 18, 19, 20, 21 } // Left: Idle_16..Idle_21
        };

        string[] clipNames = { "Flynn_Idle_Down", "Flynn_Idle_Up", "Flynn_Idle_Left" };
        string[] directionNames = { "Down", "Up", "Left" };
        string clipDir = "Assets/Flynn/Animations/";

        int sampleRate = 12;

        for (int d = 0; d < 3; d++)
        {
            var clip = new AnimationClip();
            clip.name = clipNames[d];
            clip.frameRate = sampleRate;
            clip.wrapMode = WrapMode.Loop;

            var settings = AnimationUtility.GetAnimationClipSettings(clip);
            settings.loopTime = true;
            AnimationUtility.SetAnimationClipSettings(clip, settings);

            // Build sprite keyframes
            var binding = EditorCurveBinding.PPtrCurve("", typeof(SpriteRenderer), "m_Sprite");
            var keyframes = new ObjectReferenceKeyframe[6];

            for (int i = 0; i < 6; i++)
            {
                string spriteName = "Idle_" + frameSets[d][i];
                Sprite sprite = null;
                if (!spriteMap.TryGetValue(spriteName, out sprite))
                {
                    Debug.LogError($"Sprite {spriteName} not found!");
                    continue;
                }
                keyframes[i] = new ObjectReferenceKeyframe
                {
                    time = i / (float)sampleRate,
                    value = sprite
                };
            }

            AnimationUtility.SetObjectReferenceCurve(clip, binding, keyframes);

            string clipPath = clipDir + clipNames[d] + ".anim";
            AssetDatabase.CreateAsset(clip, clipPath);
            Debug.Log($"Created {clipNames[d]} with 6 frames at {clipPath}");
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        // Now update the blend trees in the controller
        var controller = AssetDatabase.LoadAssetAtPath<AnimatorController>(
            "Assets/Flynn/Animations/Flynn_FrameAnimator.controller");
        if (controller == null)
        {
            Debug.LogError("Flynn_FrameAnimator.controller not found");
            return;
        }

        // Find the Idle state's blend tree
        var idleClips = new AnimationClip[]
        {
            AssetDatabase.LoadAssetAtPath<AnimationClip>(clipDir + "Flynn_Idle_Down.anim"),
            AssetDatabase.LoadAssetAtPath<AnimationClip>(clipDir + "Flynn_Idle_Up.anim"),
            AssetDatabase.LoadAssetAtPath<AnimationClip>(clipDir + "Flynn_Idle_Left.anim")
        };

        foreach (var layer in controller.layers)
        {
            var stateMachine = layer.stateMachine;
            foreach (var state in stateMachine.states)
            {
                if (state.state.name == "Idle" && state.state.motion is BlendTree blendTree)
                {
                    // Rebuild the blend tree children
                    var children = blendTree.children;
                    for (int i = 0; i < children.Length && i < idleClips.Length; i++)
                    {
                        children[i].motion = idleClips[i];
                    }
                    blendTree.children = children;
                    Debug.Log($"Updated Idle blend tree with new 6-frame clips");
                }
            }
        }

        EditorUtility.SetDirty(controller);
        AssetDatabase.SaveAssets();
        Debug.Log("Done! All 3 Idle clips rebuilt with 6 frames, blend tree updated.");
    }
}

