foreach (var layer in controller.layers)
{
    foreach (var state in layer.stateMachine.states)
    {
        if (state.state.motion is BlendTree bt)
        {
            UnityEngine.Debug.Log($"State: {state.state.name}");
            UnityEngine.Debug.Log($"  BlendParameter: {bt.blendParameter}");
            UnityEngine.Debug.Log($"  useAutomaticThresholds: {bt.useAutomaticThresholds}");
            for (int i = 0; i < bt.children.Length; i++)
            {
                var c = bt.children[i];
                string clipName = c.motion != null ? c.motion.name : "NULL";
                UnityEngine.Debug.Log($"  Child {i}: threshold={c.threshold}, motion={clipName}, scale={c.timeScale}, dir={c.directBlendParameter}");
            }
        }
    }
}

using UnityEditor.Animations;

var controller = AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(
    "Assets/Flynn/Animations/Flynn_FrameAnimator.controller");
if (controller == null) { UnityEngine.Debug.LogError("Controller not found"); return; }

string clipDir = "Assets/Flynn/Animations/";
var runDown = AssetDatabase.LoadAssetAtPath<AnimationClip>(clipDir + "Flynn_Run_Down.anim");
var runUp   = AssetDatabase.LoadAssetAtPath<AnimationClip>(clipDir + "Flynn_Run_Up.anim");
var runLeft = AssetDatabase.LoadAssetAtPath<AnimationClip>(clipDir + "Flynn_Run_Left.anim");

if (runDown == null) { UnityEngine.Debug.LogError("Run_Down clip missing"); return; }
if (runUp == null)   { UnityEngine.Debug.LogError("Run_Up clip missing"); return; }
if (runLeft == null) { UnityEngine.Debug.LogError("Run_Left clip missing"); return; }

foreach (var layer in controller.layers)
{
    foreach (var state in layer.stateMachine.states)
    {
        if (state.state.name == "Run" && state.state.motion is BlendTree bt)
        {
            var children = bt.children;
            children[0].motion = runDown;
            children[1].motion = runUp;
            children[2].motion = runLeft;
            bt.children = children;
            UnityEngine.Debug.Log("Fixed Run blend tree: Down=" + (children[0].motion != null) + ", Up=" + (children[1].motion != null) + ", Left=" + (children[2].motion != null));
        }
    }
}

EditorUtility.SetDirty(controller);
AssetDatabase.SaveAssets();
UnityEngine.Debug.Log("Run blend tree repaired.");

