var go = UnityEngine.GameObject.Find("MANAGERS");
if (go != null)
{
    UnityEngine.Debug.Log("MANAGERS found with children:");
    foreach (Transform child in go.transform)
        UnityEngine.Debug.Log("  " + child.name + " — components: " + string.Join(", ", child.GetComponents<UnityEngine.Component>().Select(c => c.GetType().Name)));
}
else
{
    UnityEngine.Debug.Log("MANAGERS not found, listing root objects:");
    var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
    foreach (var root in scene.GetRootGameObjects())
        UnityEngine.Debug.Log("  " + root.name);
}

