.hud-root {
    flex-grow: 1;
}

/* ── Battery (top-left) ─────────────────────────────────────────────────────── */

.battery {
    position: absolute;
    top: 20px;
    left: 20px;
    flex-direction: column;
    align-items: flex-start;
}

.battery-cap {
    letter-spacing: 2px;
    margin-bottom: 4px;
}

.battery-gauge {
    width: 140px;
    height: 16px;
    background-color: rgb(0, 0, 0);
    padding: 2px;
    flex-direction: row;
}

.battery-fill {
    width: 100%;
    height: 100%;
    background-color: rgb(255, 255, 255);
}

.battery-pct {
    margin-top: 4px;
}

/* ── Power Buildup (below battery) ─────────────────────────────────────────── */

.power-buildup {
    position: absolute;
    top: 72px;
    left: 20px;
    flex-direction: column;
    align-items: flex-start;
}

.power-buildup-cap {
    letter-spacing: 2px;
    margin-bottom: 4px;
}

.power-buildup-bar {
    width: 140px;
    height: 12px;
    background-color: rgb(0, 0, 0);
    padding: 2px;
    flex-direction: row;
    position: relative;
    overflow: hidden;
}

.power-buildup-perfect {
    position: absolute;
    top: 0;
    bottom: 0;
    background-color: rgba(0, 255, 200, 0.15);
    border-left-width: 1px;
    border-right-width: 1px;
    border-left-color: rgba(0, 255, 200, 0.4);
    border-right-color: rgba(0, 255, 200, 0.4);
}

.power-buildup-fill {
    width: 0%;
    height: 100%;
    background-color: rgb(255, 255, 255);
}

.power-buildup-fill--perfect {
    background-color: rgb(0, 255, 200);
}

.power-buildup-fill--flash {
    background-color: rgb(255, 255, 100);
}

.power-buildup-pct {
    margin-top: 2px;
    min-width: 28px;
}

/* ── Echo counter (top-right) ──────────────────────────────────────────────── */

.echo {
    position: absolute;
    top: 20px;
    right: 20px;
    flex-direction: row;
    align-items: center;
    background-color: rgb(0, 0, 0);
    padding-left: 12px;
    padding-right: 12px;
    padding-top: 4px;
    padding-bottom: 4px;
}

.echo-icon {
    margin-right: 8px;
}

.echo-count {
    min-width: 28px;
    -unity-text-align: middle-right;
}

