// Create a 256x1 color ramp texture
int w = 256, h =1;
var tex = new UnityEngine.Texture2D(w, h, UnityEngine.TextureFormat.RGBA32, false);
tex.filterMode = UnityEngine.FilterMode.Bilinear;
tex.wrapMode = UnityEngine.TextureWrapMode.Clamp;

for (int x = 0; x < w; x++)
{
    float t = x / (float)(w - 1);
    float r, g, b;

    if (t < 0.25f)
    {
        float s = t / 0.25f;
        r = UnityEngine.Mathf.Lerp(0.06f, 0.18f, s);
        g = UnityEngine.Mathf.Lerp(0.07f, 0.17f, s);
        b = UnityEngine.Mathf.Lerp(0.14f, 0.28f, s);
    }
    else if (t < 0.5f)
    {
        float s = (t - 0.25f) / 0.25f;
        r = UnityEngine.Mathf.Lerp(0.18f, 0.40f, s);
        g = UnityEngine.Mathf.Lerp(0.17f, 0.32f, s);
        b = UnityEngine.Mathf.Lerp(0.28f, 0.30f, s);
    }
    else if (t < 0.75f)
    {
        float s = (t - 0.5f) / 0.25f;
        r = UnityEngine.Mathf.Lerp(0.40f, 0.68f, s);
        g = UnityEngine.Mathf.Lerp(0.32f, 0.58f, s);
        b = UnityEngine.Mathf.Lerp(0.30f, 0.45f, s);
    }
    else
    {
        float s = (t - 0.75f) / 0.25f;
        r = UnityEngine.Mathf.Lerp(0.68f, 0.97f, s);
        g = UnityEngine.Mathf.Lerp(0.58f, 0.93f, s);
        b = UnityEngine.Mathf.Lerp(0.45f, 0.82f, s);
    }

    tex.SetPixel(x, 0, new UnityEngine.Color(r, g, b, 1f));
}

tex.Apply();

